#!/bin/sh
# Claude usage agent - self installer for Linux (and macOS), generated by the
# server at __SERVER__ with its URL and agent token built in. Keep it private.
#
#   sh claude-usage-agent-linux.sh               install, send once, schedule every 30 minutes
#   sh claude-usage-agent-linux.sh --uninstall   remove the schedule and the agent
#
# Needs Python 3.9+. Installs to ~/.local/share/claude-usage-agent and runs it
# from cron (or a systemd user timer when cron isn't available).
set -eu

DIR="${XDG_DATA_HOME:-$HOME/.local/share}/claude-usage-agent"
LOG="$HOME/.claude/usage-agent.log"
MARK="# claude-usage-agent"
UNIT="$HOME/.config/systemd/user/claude-usage-agent"

unschedule() {
    if command -v crontab >/dev/null 2>&1; then
        (crontab -l 2>/dev/null || true) | grep -vF "$MARK" | crontab - || true
    fi
    if [ -f "$UNIT.timer" ]; then
        systemctl --user disable --now claude-usage-agent.timer >/dev/null 2>&1 || true
        rm -f "$UNIT.timer" "$UNIT.service"
        systemctl --user daemon-reload >/dev/null 2>&1 || true
    fi
}

if [ "${1:-}" = "--uninstall" ]; then
    unschedule
    rm -rf "$DIR"
    echo "Claude usage agent removed (log kept at $LOG)."
    exit 0
fi

PY=""
for p in python3 python; do
    if command -v "$p" >/dev/null 2>&1 && "$p" -c 'import sys; sys.exit(sys.version_info < (3, 9))' 2>/dev/null; then
        PY=$(command -v "$p")
        break
    fi
done
[ -n "$PY" ] || { echo "Python 3.9 or newer is needed (install python3 and run this again)." >&2; exit 1; }

mkdir -p "$DIR" "$(dirname "$LOG")"
echo "__AGENT_B64__" | "$PY" -c 'import base64, sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' > "$DIR/claude_usage_agent.py"
(umask 077 && echo "__CONFIG_B64__" | "$PY" -c 'import base64, sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' > "$DIR/agent.json")
chmod 600 "$DIR/agent.json"

echo "Installed to $DIR - sending usage once now..."
"$PY" "$DIR/claude_usage_agent.py" || echo "First send failed (see above); the schedule will retry." >&2

unschedule
if command -v crontab >/dev/null 2>&1; then
    { (crontab -l 2>/dev/null || true); echo "*/30 * * * * \"$PY\" \"$DIR/claude_usage_agent.py\" --log \"$LOG\" $MARK"; } | crontab -
    echo "Scheduled with cron every 30 minutes. Log: $LOG"
elif systemctl --user show-environment >/dev/null 2>&1; then
    mkdir -p "$(dirname "$UNIT")"
    printf '[Unit]\nDescription=Claude usage agent\n\n[Service]\nType=oneshot\nExecStart="%s" "%s" --log "%s"\n' \
        "$PY" "$DIR/claude_usage_agent.py" "$LOG" > "$UNIT.service"
    printf '[Unit]\nDescription=Send Claude usage every 30 minutes\n\n[Timer]\nOnBootSec=2min\nOnUnitActiveSec=30min\nPersistent=true\n\n[Install]\nWantedBy=timers.target\n' \
        > "$UNIT.timer"
    systemctl --user daemon-reload
    systemctl --user enable --now claude-usage-agent.timer >/dev/null
    echo "Scheduled with a systemd user timer every 30 minutes. Log: $LOG"
else
    echo "No cron or systemd found: run \"$PY $DIR/claude_usage_agent.py\" yourself to send usage." >&2
fi
